    '#los-help .lh-log{flex:1;overflow-y:auto;padding:14px 16px;display:flex;flex-direction:column;gap:12px;overscroll-behavior:contain;}',
    '#los-help .lh-msg-user{align-self:flex-end;max-width:85%;padding:8px 12px;border-radius:14px 14px 4px 14px;background:var(--lh-btn-bg);color:var(--lh-btn-fg);white-space:pre-wrap;word-wrap:break-word;}',
    '#los-help .lh-msg-bot{align-self:stretch;}',
